'use strict';
const path=require('node:path'),crypto=require('node:crypto'),Core=require('./app'),D=require('./profile-draft-core'),C=require('./profile-library-core'),Completion=require('./profile-completion-core');
function createLibrary({authorize,guard,profiles,cardVault,chooseSave,confirmExport,writeFile=require('node:fs/promises').writeFile,getCustomerProfileSource,now=Date.now,uuid=crypto.randomUUID}={}){
 const plans=new Map(),epochs=new Map();
 const ep=e=>epochs.get(e.sender.id)||0;
 function cancel(e){epochs.set(e.sender.id,ep(e)+1);for(const [id,p] of plans)if(p.sender===e.sender.id)plans.delete(id);}
 async function access(e,p){require('./jig-field-core').scopeKey(p?.scope,p?.customerId);const epoch=ep(e);const id=await authorize(e,p.scope,p.customerId);if(p.scope==='aco'&&id!==p.customerId)throw Error('Customer vault mismatch.');guard(e,p.scope);if(ep(e)!==epoch)throw Error('Vault closed during authorization.');return {scope:p.scope,id,check:()=>{guard(e,p.scope);if(ep(e)!==epoch)throw Error('Vault closed during this operation.');}};}
 const cardKey=(s,id)=>s==='personal'?'personal:owner':id;
 function view(row){const result=Completion.inspect(row);return {id:row.id,revision:row.revision||0,retailer:row.retailer,group:row.group||row.retailer,stage:result.ready?'completed':'in-progress',missing:result.missing,label:row.label,email:row.email,data:structuredClone(row.data),source:row.source,sourceLinked:row.sourceLinked!==false,needsReview:!!row.needsReview};}
 async function list(e,p){const a=await access(e,p),rows=await profiles.fieldSnapshot(a.scope,a.id);a.check();const counts=new Map();for(const r of rows){for(const [kind,key]of Object.entries({email:C.email(C.values(r.data).email),name:C.nameKey(r.data),card:C.payment(r.data).number})){if(key){const k=r.retailer+'|'+kind+'|'+key;counts.set(k,(counts.get(k)||0)+1);}}}return {scope:a.scope,customerId:a.id,profiles:rows.map(r=>({...view(r),duplicates:Object.entries({email:C.email(C.values(r.data).email),name:C.nameKey(r.data),card:C.payment(r.data).number}).filter(([k,v])=>v&&counts.get(r.retailer+'|'+k+'|'+v)>1).map(([k])=>k)}))};}
 async function detail(e,p){const a=await access(e,p),r=await profiles.preview(a.scope,a.id,p.profileId);a.check();return view(r.profile);}
 async function importPreview(e,p){const a=await access(e,p);C.retailer(p.retailer);if(typeof p.fileName!=='string'||p.fileName!==path.basename(p.fileName)||p.fileName.length>200||typeof p.text!=='string'||Buffer.byteLength(p.text)>26*1024*1024)throw Error('Choose a local profile file.');const parsed=Core.parseFile(p.fileName,p.text);if(!parsed.records?.length||parsed.records.length>500)throw Error('Import 1-500 profiles.');
 for(const row of parsed.records)if(row.scope&&row.scope!==a.scope||row.customerId&&row.customerId!==a.id||row.acoCustomerId&&row.acoCustomerId!==a.id)throw Error('Imported profile ownership does not match this vault.');
 const data=parsed.records.map(row=>C.normalized(row,p.retailer));if(data.some(x=>JSON.stringify(x).length>16000))throw Error('A profile exceeds the supported record size.');const existing=await profiles.fieldSnapshot(a.scope,a.id),duplicates=C.collisions(data,existing,p.retailer),token=uuid();a.check();for(const [id,plan]of plans)if(now()-plan.at>600000)plans.delete(id);if(plans.size>30)throw Error('Close an older import preview first.');plans.set(token,{sender:e.sender.id,scope:a.scope,id:a.id,retailer:p.retailer,data,at:now(),epoch:ep(e)});return {token,count:data.length,profiles:data.map((row,i)=>({email:C.values(row).email,name:C.nameKey(row),cardLast4:C.payment(row).number.slice(-4),duplicates:duplicates[i]}))};}
 async function withCards(a,ids,fn){if(!Array.isArray(ids)||ids.length>500||ids.some(x=>typeof x!=='string')||new Set(ids).size!==ids.length)throw Error('Choose saved cards in this vault.');return ids.length?cardVault(a.scope).withSelectedForJig(cardKey(a.scope,a.id),ids,fn):fn([]);}
 function resolve(data,retailer,ctx,options,cards){const existing=ctx.rows.filter(x=>x.retailer===retailer),seen=existing.map(x=>({retailer,data:x.data})),usedNames=new Set(existing.map(x=>C.nameKey(x.data))),usedEmails=new Set(existing.map(x=>C.email(x.email))),usedCards=new Set(ctx.rows.map(x=>C.payment(x.data).number));const added=[];
 for(let index=0;index<data.length;index++){let row=structuredClone(data[index]);const flags=C.collisions([row],seen,retailer)[0];
  if(options.name&&(flags.includes('name')||options.all)){row=C.randomName(row,usedNames);}
  if(options.email&&(flags.includes('email')||options.all)){const email=ctx.emails.find(x=>x.retailer===retailer&&!x.profileId&&!usedEmails.has(x.email));if(!email)throw Error('Not enough unused emails in this vault and retailer.');row.email=email.email;email.profileId='pending-'+index;}
  if(options.card&&(flags.includes('card')||options.all)){const card=cards.find(c=>!c.previouslyAssigned&&!usedCards.has(c.number));if(!card)throw Error('Not enough unused cards in this vault.');C.putCard(row,card);usedCards.add(card.number);}
  const after=C.collisions([row],seen,retailer)[0];if(after.includes('email'))throw Error('Duplicate email remains. Select Replace duplicate emails.');if(after.length&&!options.allowShared)throw Error('Duplicate name or card remains. Repair it or explicitly allow shared names/cards.');
  if(!C.values(row).email)throw Error('A profile email is missing.');usedEmails.add(C.email(row.email));usedNames.add(C.nameKey(row));seen.push({retailer,data:row});added.push(row);
 }return added;}
 async function importCommit(e,p){const plan=plans.get(p.token);if(!plan||plan.sender!==e.sender.id||now()-plan.at>600000||plan.epoch!==ep(e))throw Error('Import preview expired. Preview again.');const a=await access(e,{scope:plan.scope,customerId:plan.id});if(p.confirmed!==true)throw Error('Review the import first.');return withCards(a,p.cardIds||[],cards=>profiles.libraryTransaction(a.scope,a.id,ctx=>{if(plans.get(p.token)!==plan)throw Error('Import was already saved.');const data=resolve(plan.data,plan.retailer,ctx,p.repairs||{},cards),added=data.map(row=>{const id=uuid(),email=C.email(row.email),entry={id,retailer:plan.retailer,email,label:C.values(row).label||email,group:String(p.group||plan.retailer).slice(0,100),source:'owner-created-profile',status:'active',jiggedAt:p.alreadyJigged?new Date(now()).toISOString():null,createdAt:new Date(now()).toISOString(),revision:0,data:row,format:C.format(plan.retailer),assetRefs:{}};for(const bank of ctx.emails)if(bank.retailer===plan.retailer&&bank.email===email&&(!bank.profileId||String(bank.profileId).startsWith('pending-')))bank.profileId=id;ctx.rows.push(entry);ctx.audit('library-import',email,{retailer:plan.retailer});return entry;});plans.delete(p.token);return {imported:added.length};},a.check));}
 async function repair(e,p){const a=await access(e,p);return withCards(a,p.cardIds||[],cards=>profiles.libraryTransaction(a.scope,a.id,ctx=>{const row=ctx.rows.find(x=>x.id===p.profileId);if(!row||row.revision!==p.revision)throw Error('Profile changed. Reopen it.');const peers=ctx.rows.filter(x=>x.id!==row.id),target={...ctx,rows:peers};const [data]=resolve([row.data],row.retailer,target,{...p.repairs,all:true,allowShared:true},cards);row.data=data;row.email=C.email(data.email);row.revision++;row.manualOverride=true;for(const bank of ctx.emails)if(bank.email===row.email&&bank.retailer===row.retailer&&String(bank.profileId).startsWith('pending-'))bank.profileId=row.id;ctx.audit('library-repair',row.email,{retailer:row.retailer});return {updated:true};},a.check));}
 async function edit(e,p){const a=await access(e,p);return profiles.libraryTransaction(a.scope,a.id,ctx=>{const row=ctx.rows.find(x=>x.id===p.profileId);if(!row||row.revision!==p.revision)throw Error('Profile changed. Reopen it.');const data=D.manualEdit(row.data,p.fields),email=C.email(data.email);if(ctx.rows.some(x=>x.id!==row.id&&x.retailer===row.retailer&&x.email===email))throw Error('Email already used in this retailer pool.');if(p.card){const c=p.card;if(!/^\d{12,19}$/.test(String(c.number||'').replace(/\D/g,''))||!/^(0[1-9]|1[0-2])$/.test(c.month||'')||!/^20\d\d$/.test(c.year||'')||!String(c.cardholder||'').trim()||String(c.cardholder).length>120||String(c.customSecurityCode||'').length>64)throw Error('Enter complete card number, holder and expiration.');C.putCard(data,c);}row.data=data;row.email=email;row.label=C.values(data).label;row.group=String(p.group||row.group||row.retailer).slice(0,100);row.revision++;row.manualOverride=true;row.needsReview=false;if(row.pendingSourceHash){row.sourceHash=row.pendingSourceHash;delete row.pendingSourceHash;}for(const bank of ctx.emails)if(bank.email===email&&bank.retailer===row.retailer&&!bank.profileId)bank.profileId=row.id;ctx.audit('library-edit',email,{retailer:row.retailer});return {updated:true};},a.check);}
 async function exportFile(e,p){const a=await access(e,p);C.retailer(p.retailer);if(!Array.isArray(p.profileIds)||!p.profileIds.length||p.profileIds.length>500||new Set(p.profileIds).size!==p.profileIds.length)throw Error('Select 1-500 completed profiles.');const all=await profiles.fieldSnapshot(a.scope,a.id),rows=p.profileIds.map(id=>all.find(x=>x.id===id&&x.retailer===p.retailer));if(rows.some(x=>!x||!Completion.inspect(x).ready))throw Error('Every exported profile must be complete and belong to this vault/retailer.');const content=C.exportRows(rows,p.retailer,p.customerName||'Personal');if(!await confirmExport(e))return {cancelled:true};const ext=path.extname(content.name),choice=await chooseSave(e,{name:content.name,extension:ext.slice(1)});if(choice.canceled||!choice.filePath)return {cancelled:true};if(path.extname(choice.filePath)!==ext)throw Error('Keep the retailer export format.');const latest=await profiles.fieldSnapshot(a.scope,a.id);if(rows.some(x=>require('./jig-field-core').hash(x)!==require('./jig-field-core').hash(latest.find(y=>y.id===x.id))))throw Error('Profiles changed while exporting. Try again.');a.check();await writeFile(choice.filePath,content.body,{encoding:'utf8',mode:0o600});return {saved:true,count:rows.length,name:path.basename(choice.filePath)};}
 async function syncCustomer(e,p){if(p?.scope!=='aco')throw Error('Linked website profiles can only enter that customer vault.');const a=await access(e,p);if(!getCustomerProfileSource)throw Error('Customer profile synchronization unavailable.');const source=await getCustomerProfileSource(a.id);if(source.customer?.id!==a.id)throw Error('Website customer identity mismatch.');a.check();if((source.linked||[]).some(x=>x.customerId!==a.id))throw Error('Linked source contains a different customer.');const active=(source.linked||[]).filter(x=>x.active),createdAt=new Date(now()).toISOString();
 return profiles.libraryTransaction('aco',a.id,ctx=>{let created=0,updated=0,needsReview=0;const keys=new Set();for(let i=0;i<active.length;i++){const item=active[i],r=C.retailer(item.retailer),key=r+'|'+item.assignmentId;keys.add(key);const previous=ctx.rows.find(x=>x.remoteKey===key)||ctx.rows.find(x=>x.retailer===r&&x.email===C.email(item.data.email)&&!x.remoteKey&&!x.manualOverride),data=C.jig(C.normalized(item.data,r),r,i,ctx.settings[r]?.rules||C.defaultRules());if(C.format(r)==='valor'){const hex=crypto.createHash('sha256').update(a.id+'|'+key).digest('hex');data.id=previous?.data?.id||hex.slice(0,8)+'-'+hex.slice(8,12)+'-'+hex.slice(12,16)+'-'+hex.slice(16,20)+'-'+hex.slice(20,32);}const hash=require('./jig-field-core').hash(data);if(previous){previous.remoteKey=key;previous.source='website-linked-profile';if(previous.sourceLinked===false)previous.revision++;previous.sourceLinked=true;if(previous.sourceHash!==hash){if(previous.manualOverride){previous.needsReview=true;previous.pendingSourceHash=hash;needsReview++;}else{previous.data=data;previous.email=C.email(data.email);previous.revision++;previous.sourceHash=hash;updated++;}}continue;}if(ctx.rows.some(x=>x.retailer===r&&x.email===C.email(data.email))){needsReview++;continue;}ctx.rows.push({id:uuid(),retailer:r,email:C.email(data.email),label:source.customer.name+' '+(i+1),group:source.customer.name,source:'website-linked-profile',status:'active',createdAt,revision:0,data,format:C.format(r),remoteKey:key,sourceHash:hash,sourceLinked:true,jiggedAt:createdAt,assetRefs:{}});created++;ctx.audit('linked-profile-created',C.email(data.email),{retailer:r});}
 for(const row of ctx.rows)if(row.source==='website-linked-profile'&&row.sourceLinked!==false&&!keys.has(row.remoteKey)){row.sourceLinked=false;row.revision++;}return {created,updated,needsReview};},a.check);}
 async function rules(e,p){const a=await access(e,p);C.retailer(p.retailer);const settings=await profiles.librarySettings(a.scope,a.id);a.check();return {selected:settings[p.retailer]?.rules||C.defaultRules(),options:Core.RULES.filter(x=>!/^prefix_three/.test(x.id)).map(x=>({id:x.id,label:x.label}))};}
 async function saveRules(e,p){const a=await access(e,p);C.retailer(p.retailer);if(!Array.isArray(p.rules)||p.rules.length>100||new Set(p.rules).size!==p.rules.length||p.rules.some(id=>typeof id!=='string'||/^prefix_three/.test(id)||!Core.RULES.some(x=>x.id===id)))throw Error('Choose supported jig rules for this retailer.');return profiles.libraryTransaction(a.scope,a.id,ctx=>{ctx.settings[p.retailer]={rules:p.rules};return {saved:true};},a.check);}
 return {list,detail,importPreview,importCommit,repair,edit,exportFile,syncCustomer,rules,saveRules,cancel};
}
function registerLibrary(options){const service=createLibrary(options);for(const method of ['list','detail','importPreview','importCommit','repair','edit','exportFile','syncCustomer','rules','saveRules'])options.ipcMain.handle('profile:library:'+method,(e,p)=>service[method](e,p));options.ipcMain.handle('profile:library:cancel',e=>{options.requireOwner(e);return service.cancel(e);});return service;}
module.exports={createLibrary,registerLibrary};
